INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (127, 'hotResumoCr', 'Visao Resumo do CR em 1 ida (ORC,REAL,REAL_ANT,DRV_CFG como JSON). Params: crId,cicloId,ano,anoPrev.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''MES'',x.MES,''VALOR'',x.VALOR,''CONTA_CODIGO'',x.CONTA_CODIGO,''CONTA_NOME'',x.CONTA_NOME)) FROM (SELECT o.CONTA_ID, o.MES, SUM(o.VALOR) AS VALOR, cc.CODIGO AS CONTA_CODIGO, cc.NOME AS CONTA_NOME FROM ORCAMENTO o JOIN CONTA_CONTABIL cc ON cc.ID = o.CONTA_ID WHERE o.CICLO_ID = {{cicloId}} AND o.CR_ID = {{crId}} GROUP BY o.CONTA_ID, o.MES, cc.CODIGO, cc.NOME) x),JSON_ARRAY()) AS ORC,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''MES'',x.MES,''VALOR'',x.VALOR)) FROM (SELECT rc.CONTA_ID, rc.MES, SUM(rc.VALOR) AS VALOR FROM REALIZADO_CONTABIL rc WHERE rc.ANO = {{ano}} AND rc.CR_ID = {{crId}} GROUP BY rc.CONTA_ID, rc.MES) x),JSON_ARRAY()) AS REAL,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''MES'',x.MES,''VALOR'',x.VALOR)) FROM (SELECT rc.CONTA_ID, rc.MES, SUM(rc.VALOR) AS VALOR FROM REALIZADO_CONTABIL rc WHERE rc.ANO = {{anoPrev}} AND rc.CR_ID = {{crId}} GROUP BY rc.CONTA_ID, rc.MES) x),JSON_ARRAY()) AS REAL_ANT,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''CONTA_ID'',x.CONTA_ID,''DRIVER_TIPO'',x.DRIVER_TIPO)) FROM (SELECT DISTINCT crc.CONTA_ID, d.NOME AS DRIVER_TIPO FROM CR_CONTA crc LEFT JOIN CONTA_DRIVER_EXCECAO cde ON cde.CR_ID = crc.CR_ID AND cde.CONTA_ID = crc.CONTA_ID AND cde.ATIVO = true LEFT JOIN CONTA_DRIVER cd ON cd.CONTA_ID = crc.CONTA_ID LEFT JOIN DRIVERS d ON d.ID = COALESCE(cde.PACOTE_ID, cd.PACOTE_ID, cde.DRIVER_ID, cd.DRIVER_ID) WHERE crc.CR_ID = {{crId}} AND crc.ATIVO = true AND d.ID IS NOT NULL AND d.ATIVO = ''true'') x),JSON_ARRAY()) AS DRV_CFG', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
